package org.kanger.storage.dumb2;
import java.util.*;import java.nio.file.*;import org.kanger.*;import org.kanger.storage.dumb2.ContextNativeCandidateLeaseMatrix.Fixture;
public final class ContextRelationalModelPublicationRunner {
 static int checks;static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}static ContextSignedModelRequest req(String s){return new ContextSignedModelRequest(s,Collections.emptyMap());}static Set<String> primary(Fixture f)throws Exception{return ContextNativeCommitGuardMatrix.primary(f);}
 public static void main(String[] args){try{Path d=Files.createTempDirectory("relational-publication-");System.setProperty("user.home",d.toString());String universal="!@u @v rel(u,v);";
  try(Fixture f=new Fixture(d,"Universal")){String[] out=ContextAutomaticModelMatrix.console(f.mind,"ctx candidate model write \""+universal+"\"\n");require(out[0].contains("MODEL WRITE: PUBLISHED")&&out[1].trim().isEmpty(),"actual Console relational universal publication");}
  try(Fixture f=new Fixture(d,"Universal")){require(primary(f).equals(Collections.singleton(universal)),"only whole relational original persisted, no model cells");require(Boolean.TRUE.equals(f.mind.query("?rel(42,43);",null,false)),"unmentioned admissible values follow universal rule after reopen");}
  try(Fixture f=new Fixture(d,"Ordered")){require(f.db.publishSignedModelCandidate(f.mind,req("!rel(1,2);")).status==ContextSignedModelPublication.Status.PUBLISHED,"first tuple accepted");require(f.db.publishSignedModelCandidate(f.mind,req("!~rel(2,1);")).status==ContextSignedModelPublication.Status.PUBLISHED,"same predicate opposite ordered tuple accepted with nonuniform model");}
  try(Fixture f=new Fixture(d,"Ordered")){require(primary(f).size()==2&&Boolean.TRUE.equals(f.mind.query("?rel(1,2);",null,false))&&Boolean.TRUE.equals(f.mind.query("?~rel(2,1);",null,false)),"ordered tuple knowledge durable, no collapsed arity/truth");}
  List<String> constants=new ArrayList<>();for(int i=1;i<=64;i++)constants.add(Integer.toString(i));String many="!wide("+String.join(",",constants)+");";try(Fixture f=new Fixture(d,"WideConstants")){String[] out=ContextAutomaticModelMatrix.console(f.mind,"ctx candidate model write \""+many+"\" points=64\n");require(out[0].contains("MODEL WRITE: PUBLISHED")&&out[1].trim().isEmpty(),"actual Console configurable64-point/64-constant tuple");}try(Fixture f=new Fixture(d,"WideConstants")){require(primary(f).equals(Collections.singleton(many)),"all64 typed positions retained as ONE original after cold reopen");}
  try(Fixture f=new Fixture(d,"Ordered")){require(f.mind.query("?rel(3,4);",null,false)==null,"unchosen tuple remains unknown in actual Core; model truth/default is not knowledge");}
  String bundle="!$u rel(u,1)&&~rel(1,u);";try(Fixture f=new Fixture(d,"Witness")){require(f.db.publishSignedModelCandidate(f.mind,req(bundle)).status==ContextSignedModelPublication.Status.PUBLISHED,"fresh basis grows for correlated relational witness");require(primary(f).equals(Collections.singleton(bundle)),"no chosen witness value published as extra fact");}
  ContextNativeCandidateLeaseMatrix.create(d,"Positive","!rel(1,2);");try(Fixture f=new Fixture(d,"Refuted")){f.db.connectContext("Positive");long before=f.db.getRevision();ContextSignedModelPublication no=f.db.publishSignedModelCandidate(f.mind,new ContextSignedModelRequest("!@u @v ~rel(u,v);",Collections.singletonMap("cells",0)));require(no.status==ContextSignedModelPublication.Status.REFUTED&&no.evidence!=null,"actual negative proof precedes zero model cells");no.evidence.check(64000000,64);require(primary(f).isEmpty()&&before==f.db.getRevision(),"sourced refusal atomic");}
  try(Fixture f=new Fixture(d,"Limited")){long before=f.db.getRevision();ContextSignedModelPublication no=f.db.publishSignedModelCandidate(f.mind,new ContextSignedModelRequest(universal,Collections.singletonMap("candidates",1)));require(no.status==ContextSignedModelPublication.Status.INCOMPLETE,"one failed relational candidate is not no-model proof");require(primary(f).isEmpty()&&before==f.db.getRevision(),"candidate-bound failure atomic");}
  System.out.println("RELATIONAL_MODEL_PUBLICATION actualConsole=true allAdmissibleReopen=true orderedNonuniformTuples=true correlatedWitness=true noModelFactsPersisted=true sealedRefutationFirst=true atomicBudgetFailure=true");System.out.println("CONTEXT_RELATIONAL_MODEL_PUBLICATION_PASS checks="+checks);System.exit(0);
 }catch(Throwable t){t.printStackTrace();System.exit(1);}}
}
